/* =============================================================================
   REG-05 · Introducción a las claves E2EE (Módulo 01 · Onboarding, Fase B)

   Pantalla explicativa previa a REG-06. Todos los colores salen de `tokens.css`:
   aquí no hay ningún hex ni ningún rgb(). Las longitudes que no tienen token
   (tamaños de tipo y espaciados concretos del HTML aprobado) se quedan en px,
   porque el vocabulario cerrado es de color, no de medida.

   Nota de paleta: `tokens.css` no tiene blanco puro; allí donde el HTML aprobado
   pinta texto sobre latón o sobre el azul de acción se usa `--bw-cold-white`,
   que es el claro más cercano del vocabulario.
   ========================================================================== */

/* Raíz: hija directa de `.bwcnt` (que es `overflow: hidden`), así que scrollea
   ella. Mismo patrón ya resuelto en Welcome.module.css. */
.screen {
  flex: 1;
  min-height: 0;
  overflow-y: auto;
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 52px 48px 56px;
}

/* La columna de contenido del HTML aprobado: centrada y de hasta 600 px. */
.screen > * {
  width: 100%;
  max-width: 600px;
}

/* ── Pasos del registro ──────────────────────────────────────────────────── */

.steps {
  display: flex;
  align-items: center;
  list-style: none;
  margin: 0 0 36px;
  padding: 0;
}

.step {
  display: flex;
  align-items: center;
  gap: 8px;
  flex: 1;
  min-width: 0;
  font-family: var(--bw-font-mono);
  font-size: 10px;
  font-weight: 500;
  text-transform: uppercase;
  letter-spacing: var(--bw-ls-brand);
  white-space: nowrap;
}

/* El último paso no arrastra línea: se ajusta a su contenido. */
.step:last-child {
  flex: 0 1 auto;
}

.stepLine {
  flex: 1;
  height: 1px;
  min-width: 12px;
  margin: 0 10px;
  background: var(--bw-line-steel);
}

.stepDot {
  width: 20px;
  height: 20px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  font-family: var(--bw-font-mono);
  font-size: 10px;
  font-weight: 600;
}

/* Hecho: latón. */
.stepDone {
  color: var(--bw-brass);
}

.stepDone .stepDot {
  background: var(--bw-brass);
  color: var(--bw-cold-white);
}

/* Actual: azul de acción. */
.stepActive {
  color: var(--bw-calibration-blue);
}

.stepActive .stepDot {
  background: var(--bw-calibration-blue);
  color: var(--bw-cold-white);
}

/* Pendiente: gris. */
.stepPending {
  color: var(--bw-input-placeholder);
}

.stepPending .stepDot {
  background: var(--bw-cold-white);
  color: var(--bw-input-placeholder);
  border: 1px solid var(--bw-line-steel-strong);
}

/* ── Antetítulo y título ─────────────────────────────────────────────────── */

.eyebrow {
  margin: 0 0 10px;
  font-family: var(--bw-font-title);
  font-weight: 600;
  font-size: 11px;
  text-transform: uppercase;
  letter-spacing: var(--bw-ls-eyebrow);
  color: var(--bw-brass);
}

.title {
  margin: 0 0 36px;
  font-family: var(--bw-font-title);
  font-weight: 700;
  font-size: 24px;
  line-height: 1.25;
  letter-spacing: 0.3px;
  color: var(--bw-deep-steel);
}

/* ── Los tres bloques ────────────────────────────────────────────────────── */

.blocks {
  display: flex;
  flex-direction: column;
  gap: 14px;
  margin-bottom: 22px;
}

.block {
  display: flex;
  align-items: flex-start;
  gap: 18px;
  padding: 20px 22px;
  border: 1px solid var(--bw-line-steel);
  border-radius: 5px;
  background: var(--bw-surface-mist);
}

.blockIcon {
  width: 44px;
  height: 44px;
  border-radius: 10px;
  background: var(--bw-icon-tint-brass);
  border: 1px solid var(--bw-brass-border);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  color: var(--bw-brass);
}

.blockBody {
  display: flex;
  flex-direction: column;
  gap: 5px;
  padding-top: 2px;
}

.blockTitle {
  margin: 0;
  font-family: var(--bw-font-title);
  font-weight: 600;
  font-size: 14px;
  color: var(--bw-deep-steel);
}

.blockDesc {
  margin: 0;
  font-size: 13px;
  line-height: 1.6;
  color: var(--bw-text-secondary);
}

/* ── Aviso ───────────────────────────────────────────────────────────────── */

.notice {
  display: flex;
  align-items: flex-start;
  gap: 10px;
  margin-bottom: 28px;
  padding: 14px 16px;
  border-left: 3px solid var(--bw-brass);
  border-radius: 0 var(--bw-radius) var(--bw-radius) 0;
  background: var(--bw-tag-bg);
  font-size: 13px;
  line-height: 1.6;
  color: var(--bw-text-secondary);
}

.noticeIcon {
  flex-shrink: 0;
  margin-top: 1px;
  color: var(--bw-brass);
}

.noticeText {
  margin: 0;
}

/* El HTML aprobado usa un latón más oscuro para el énfasis; no hay token propio
   de ese tono, así que se queda el latón de acento. */
.noticeText strong {
  font-weight: 600;
  color: var(--bw-brass);
}

/* ── Botón primario ──────────────────────────────────────────────────────── */

.primary {
  width: 100%;
  padding: 14px 20px;
  border: none;
  border-radius: var(--bw-radius);
  background: var(--bw-calibration-blue);
  font-family: var(--bw-font-body);
  font-size: 14px;
  font-weight: 600;
  color: var(--bw-cold-white);
  cursor: pointer;
  transition: background 0.15s;
}

.primary:hover {
  background: var(--bw-primary-dark);
}

.primary:focus-visible {
  outline: 2px solid var(--bw-primary-dark);
  outline-offset: 2px;
}
